package ai.nexusone.service;
import ai.nexusone.dto.*;import ai.nexusone.entity.FuturePredictionIntelligenceReport;import ai.nexusone.enums.*;import ai.nexusone.exception.FuturePredictionIntelligenceNotFoundException;import ai.nexusone.repository.FuturePredictionIntelligenceRepository;import java.time.LocalDateTime;import java.util.List;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class FuturePredictionIntelligenceService{private final FuturePredictionIntelligenceRepository repo;public FuturePredictionIntelligenceService(FuturePredictionIntelligenceRepository r){repo=r;}
@Transactional public FuturePredictionIntelligenceResponse generate(FuturePredictionIntelligenceRequest q){var x=new FuturePredictionIntelligenceReport();x.setTitle(q.title());x.setFutureOutlook(q.futureOutlook());x.setTechnologyTrendForecast(q.technologyTrendForecast());x.setMarketEvolutionForecast(q.marketEvolutionForecast());x.setCustomerBehaviorForecast(q.customerBehaviorForecast());x.setEconomicForecast(q.economicForecast());x.setSupplyChainForecast(q.supplyChainForecast());x.setWorkforceForecast(q.workforceForecast());x.setCyberThreatForecast(q.cyberThreatForecast());x.setRegulatoryForecast(q.regulatoryForecast());x.setIndustryDisruptionForecast(q.industryDisruptionForecast());x.setStrategicRecommendations(q.strategicRecommendations());x.setTechnologyPredictionScore(q.technologyPredictionScore());x.setMarketPredictionScore(q.marketPredictionScore());x.setCustomerPredictionScore(q.customerPredictionScore());x.setEconomicPredictionScore(q.economicPredictionScore());x.setSupplyChainPredictionScore(q.supplyChainPredictionScore());x.setWorkforcePredictionScore(q.workforcePredictionScore());x.setCyberThreatPredictionScore(q.cyberThreatPredictionScore());x.setRegulatoryPredictionScore(q.regulatoryPredictionScore());x.setIndustryDisruptionPredictionScore(q.industryDisruptionPredictionScore());x.setFuturePredictionIntelligenceScore(score(q));x.setPriority(q.priority());x.setStatus(FuturePredictionStatus.GENERATED);x.setCreatedBy(q.createdBy());return map(repo.save(x));}
@Transactional(readOnly=true) public FuturePredictionIntelligenceResponse get(Long id){return map(find(id));}
@Transactional(readOnly=true) public Page<FuturePredictionIntelligenceResponse> history(Pageable p){return repo.findAll(p).map(this::map);}
@Transactional(readOnly=true) public Page<FuturePredictionIntelligenceResponse> search(String k,FuturePredictionPriority pr,FuturePredictionStatus st,Pageable p){if(k!=null&&!k.isBlank())return repo.findByTitleContainingIgnoreCaseOrFutureOutlookContainingIgnoreCaseOrStrategicRecommendationsContainingIgnoreCase(k,k,k,p).map(this::map);if(pr!=null)return repo.findByPriority(pr,p).map(this::map);if(st!=null)return repo.findByStatus(st,p).map(this::map);return history(p);}
@Transactional public FuturePredictionIntelligenceResponse review(Long id,FuturePredictionActionRequest q){var x=find(id);require(x,FuturePredictionStatus.GENERATED,"Only GENERATED reports can be reviewed");x.setStatus(FuturePredictionStatus.REVIEWED);x.setReviewedBy(q.actionBy());x.setReviewedAt(LocalDateTime.now());return map(repo.save(x));}
@Transactional public FuturePredictionIntelligenceResponse approve(Long id,FuturePredictionActionRequest q){var x=find(id);require(x,FuturePredictionStatus.REVIEWED,"Only REVIEWED reports can be approved");x.setStatus(FuturePredictionStatus.APPROVED);x.setDecidedBy(q.actionBy());x.setDecidedAt(LocalDateTime.now());return map(repo.save(x));}
@Transactional public FuturePredictionIntelligenceResponse reject(Long id,FuturePredictionActionRequest q){var x=find(id);if(x.getStatus()!=FuturePredictionStatus.GENERATED&&x.getStatus()!=FuturePredictionStatus.REVIEWED)throw new IllegalArgumentException("Only GENERATED or REVIEWED reports can be rejected");x.setStatus(FuturePredictionStatus.REJECTED);x.setDecidedBy(q.actionBy());x.setDecidedAt(LocalDateTime.now());return map(repo.save(x));}
@Transactional public FuturePredictionIntelligenceResponse publish(Long id,FuturePredictionActionRequest q){var x=find(id);require(x,FuturePredictionStatus.APPROVED,"Only APPROVED reports can be published");x.setStatus(FuturePredictionStatus.PUBLISHED);x.setPublishedBy(q.actionBy());x.setPublishedAt(LocalDateTime.now());return map(repo.save(x));}
@Transactional(readOnly=true) public FuturePredictionAnalyticsResponse analytics(){List<FuturePredictionIntelligenceReport>a=repo.findAll();return new FuturePredictionAnalyticsResponse(a.size(),count(FuturePredictionStatus.GENERATED),count(FuturePredictionStatus.REVIEWED),count(FuturePredictionStatus.APPROVED),count(FuturePredictionStatus.REJECTED),count(FuturePredictionStatus.PUBLISHED),avg(a,0),avg(a,1),avg(a,2),avg(a,3),avg(a,4),avg(a,5),avg(a,6),avg(a,7),avg(a,8),round(a.stream().mapToDouble(FuturePredictionIntelligenceReport::getFuturePredictionIntelligenceScore).average().orElse(0)));}
private double score(FuturePredictionIntelligenceRequest q){return round(q.technologyPredictionScore()*0.15+q.marketPredictionScore()*0.12+q.customerPredictionScore()*0.1+q.economicPredictionScore()*0.1+q.supplyChainPredictionScore()*0.1+q.workforcePredictionScore()*0.08+q.cyberThreatPredictionScore()*0.15+q.regulatoryPredictionScore()*0.08+q.industryDisruptionPredictionScore()*0.12);}private double avg(List<FuturePredictionIntelligenceReport>a,int f){return round(a.stream().mapToDouble(x->switch(f){case 0->x.getTechnologyPredictionScore();case 1->x.getMarketPredictionScore();case 2->x.getCustomerPredictionScore();case 3->x.getEconomicPredictionScore();case 4->x.getSupplyChainPredictionScore();case 5->x.getWorkforcePredictionScore();case 6->x.getCyberThreatPredictionScore();case 7->x.getRegulatoryPredictionScore();default->x.getIndustryDisruptionPredictionScore();}).average().orElse(0));}private long count(FuturePredictionStatus s){return repo.countByStatus(s);}private double round(double v){return Math.round(v*100.0)/100.0;}private void require(FuturePredictionIntelligenceReport x,FuturePredictionStatus s,String m){if(x.getStatus()!=s)throw new IllegalArgumentException(m);}private FuturePredictionIntelligenceReport find(Long id){return repo.findById(id).orElseThrow(()->new FuturePredictionIntelligenceNotFoundException(id));}private FuturePredictionIntelligenceResponse map(FuturePredictionIntelligenceReport x){return new FuturePredictionIntelligenceResponse(x.getId(),x.getTitle(),x.getFutureOutlook(),x.getTechnologyTrendForecast(),x.getMarketEvolutionForecast(),x.getCustomerBehaviorForecast(),x.getEconomicForecast(),x.getSupplyChainForecast(),x.getWorkforceForecast(),x.getCyberThreatForecast(),x.getRegulatoryForecast(),x.getIndustryDisruptionForecast(),x.getStrategicRecommendations(),x.getTechnologyPredictionScore(),x.getMarketPredictionScore(),x.getCustomerPredictionScore(),x.getEconomicPredictionScore(),x.getSupplyChainPredictionScore(),x.getWorkforcePredictionScore(),x.getCyberThreatPredictionScore(),x.getRegulatoryPredictionScore(),x.getIndustryDisruptionPredictionScore(),x.getFuturePredictionIntelligenceScore(),x.getPriority(),x.getStatus(),x.getCreatedBy(),x.getReviewedBy(),x.getReviewedAt(),x.getDecidedBy(),x.getDecidedAt(),x.getPublishedBy(),x.getPublishedAt(),x.getCreatedAt(),x.getUpdatedAt());}}
